options.helpers:
const handlebars = context.handlebars;

// Same blue/orange/red vocabulary the rest of the BambuLabs dashboards use.
handlebars.registerHelper('statusColor', function (status) {
  if (status === 'failed') return '#F2495C';
  if (status === 'running') return '#FF9830';
  return '#5794F2';
});

// Grafana types the date label as a time field and hands the template its
// long display form ("August 02, 2026"), which wraps the column. Neither
// convertFieldType nor its dateFormat option overrides that, so reformat
// here. Built from local date parts rather than toISOString() so the day
// cannot slip backwards across a UTC offset.
handlebars.registerHelper('isoDate', function (v) {
  const d = new Date(v);
  if (isNaN(d.getTime())) return v;
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
});

// costTime arrives in seconds. The notes this dashboard replaced showed
// "4h 26m", which is the readable form for prints measured in hours.
handlebars.registerHelper('dur', function (s) {
  const n = Number(s);
  if (!isFinite(n) || n <= 0) return '';
  const h = Math.floor(n / 3600), m = Math.round((n % 3600) / 60);
  return h ? `${h}h ${m}m` : `${m}m`;
});
